data.query:
query Query($where1: ProductionHistoryWhereInput, 
            $orderBy1: [ProductionHistoryOrderByInput!],
            $after1: String
            ){
  productionHistory: productionHistory(where: $where1, orderBy: $orderBy1, after: $after1) {
    edges {
      node {
        id
        number
        actualLaborHours
        actualMachineHours
        actualSetupHours
        earnedLaborHours
        earnedMachineHours
        earnedSetupHours
        quantity
        includeProductionCounts
        externalId
        creditedAt
        occurAt
        customData
        productionHistoryStatusId
        transactionTypeId
        workcenterId
        aggregationId
        distributionId
        distributionGroupId
        inventoryId
        kanbanCardId
        masterInventoryId
        productId
        productStrategyProcessId
        assetData
        productionRunId
        scrapReasonId
        shiftId
        workOrderId
        workOrderProcess{
          id
          unitPerCycle
        }
        workcenterId
        workcenter {
          code
          workcenterAssets {
            edges {
              node {
                id
                number
                currentCycles
                currentHours
                lifetimeCycles
                lifetimeHours
                serialized
                brand
                description
                modelNumber
                serialNumber
                inServiceAt
                lastResetAt
                newAt
                purchaseAt
                customData
                statusId
                typeId
                groupId
                supplierId
                workcenterId
                productStrategyProcessAssets {
                  edges {
                    node {
                      id
                      active
                      description
                      order
                      customData
                      assetId
                      productStrategyProcessId
                    }
                  }
                }
                workOrderProcessAssets {
                  edges {
                    node {
                      id
                      active
                      description
                      order
                      customData
                      assetId
                      workOrderProcessId
                      productStrategyProcessAssetId
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

