data.transform:
/*
$inner
USE inner join (JSONATA) to combine the 

INPUT -
1 per asset id, per ph record
{
  "id": "clwaxnjhy1b6u015dgczs8d3e",
  "units": 1,
  "hours": 0.39445305555555554,
  "cycles": 1
}

OUTPUT - 
update payload for giving new asset hours

*/

(
$1 := $state.context.LOCAL.phAssetHours;
$2 := $.asset.edges.node;

{"payload": [
    $innerJoin( 
    $1, 
    $2, 
    'id', 
    'id', 
    'currentData', 
    { 'grouped': false } ).{
      "update": {
        /* 
        Hours are handled by a different flow
        "currentHours" : newHours+$coalesce([currentData.currentHours,0]),
        "lifetimeHours" : newHours+$coalesce([currentData.lifetimeHours,0]), */
        "currentCycles" : newCycles+$coalesce([currentData.currentCycles,0]),
        "lifetimeCycles" : newCycles+$coalesce([currentData.lifetimeCycles,0])
      },
      "where": {
        "id":id
      }
    }
  ]
}
)

{
  "LOCAL": {
    "phAssetHours": $
  }
}

